document.querySelectorAll('td .dot').forEach(function (dot) {
  if (dot.dataset.auditLabelled) return;
  dot.dataset.auditLabelled = '1';
  var rgb = (getComputedStyle(dot).backgroundColor.match(/\d+/g) || [0, 0, 0]).map(Number);
  var inStock = rgb[1] > rgb[0];
  var label = document.createElement('span');
  label.className = 'audit-stock-label ' + (inStock ? 'in' : 'out');
  label.textContent = inStock ? 'In stock' : 'Out of stock';
  dot.after(label);
});

var div = document.querySelector('div.checkout');
if (div) {
  var a = document.createElement('a');
  a.href = '/checkout';
  a.className = div.className;
  a.textContent = div.textContent;
  a.style.color = '#fff';
  a.style.textDecoration = 'none';
  div.replaceWith(a);
}
